@namespace sv_c36423d92cfc47488294cd4e9e49ee07.Components.Pages.Catalog

<div class="catalog-main">
    <div class="catalog-toolbar">
        <div class="sort-control">
            <label for="sort-select">Sort by:</label>
            <select id="sort-select" value="@CurrentSort" @onchange="HandleSortChanged">
                <option value="price_asc">Price: Low to High</option>
                <option value="price_desc">Price: High to Low</option>
                <option value="name_asc">Name: A-Z</option>
                <option value="rating_desc">Rating: Highest</option>
            </select>
        </div>
        <span class="results-summary">
            Showing @StartItem–@EndItem of @TotalCount products
        </span>
    </div>

    <div class="product-grid">
        @foreach (var product in Products)
        {
            <ProductCard Product="@product"
                         OnProductSelected="OnProductSelected"
                         OnAddToCart="OnAddToCart" />
        }
    </div>

    @if (TotalPages > 1)
    {
        <CatalogPagination CurrentPage="@CurrentPage"
                           TotalPages="@TotalPages"
                           OnPageChanged="OnPageChanged" />
    }
</div>

@code {
    [Parameter]
    public List<Product> Products { get; set; } = new();

    [Parameter]
    public int TotalCount { get; set; }

    [Parameter]
    public int CurrentPage { get; set; }

    [Parameter]
    public int PageSize { get; set; }

    [Parameter]
    public int TotalPages { get; set; }

    [Parameter]
    public string CurrentSort { get; set; } = "price_asc";

    [Parameter]
    public EventCallback<string> OnSortChanged { get; set; }

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    private int StartItem => TotalCount == 0 ? 0 : (CurrentPage - 1) * PageSize + 1;
    private int EndItem => Math.Min(CurrentPage * PageSize, TotalCount);

    private async Task HandleSortChanged(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? "price_asc";
        await OnSortChanged.InvokeAsync(value);
    }
}

@page "/catalog"
@using sv_c36423d92cfc47488294cd4e9e49ee07.Components.Pages.Catalog
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<h1>Product Catalog</h1>

@if (_error is not null)
{
    <div class="catalog-error">
        <p>Something went wrong: @_error</p>
        <button @onclick="LoadDataAsync">Try Again</button>
    </div>
}
else if (_loading)
{
    <div class="catalog-loading">
        <p>Loading products...</p>
    </div>
}
else
{
    <div class="catalog-layout">
        <CatalogSidebar Categories="@_categories"
                        CurrentFilter="@_filter"
                        OnFiltersApplied="HandleFiltersApplied"
                        OnFiltersCleared="HandleFiltersCleared" />

        @if (_result is not null && _result.Items.Count > 0)
        {
            <CatalogMain Products="@_result.Items"
                         TotalCount="@_result.TotalCount"
                         CurrentPage="@_currentPage"
                         PageSize="@PageSize"
                         TotalPages="@_totalPages"
                         CurrentSort="@_sortBy"
                         OnSortChanged="HandleSortChanged"
                         OnPageChanged="HandlePageChanged"
                         OnProductSelected="HandleProductSelected"
                         OnAddToCart="HandleAddToCart" />
        }
        else
        {
            <div class="catalog-empty">
                <p>No products found matching your criteria.</p>
            </div>
        }
    </div>
}

@code {
    private const int PageSize = 12;

    private List<string>? _categories;
    private ProductFilter _filter = new(null, null, null, false);
    private PagedResult<Product>? _result;
    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private int _totalPages;
    private bool _loading = true;
    private string? _error;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    protected override async Task OnInitializedAsync()
    {
        await LoadDataAsync();
    }

    private async Task LoadDataAsync()
    {
        _loading = true;
        _error = null;

        try
        {
            var categoriesTask = ProductService.GetCategoriesAsync();
            var productsTask = ProductService.SearchAsync(_filter, _sortBy, _currentPage, PageSize);

            await Task.WhenAll(categoriesTask, productsTask);

            _categories = categoriesTask.Result;
            _result = productsTask.Result;
            _totalPages = (int)Math.Ceiling((double)_result.TotalCount / PageSize);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task SearchAsync()
    {
        _loading = true;
        _error = null;

        try
        {
            _result = await ProductService.SearchAsync(_filter, _sortBy, _currentPage, PageSize);
            _totalPages = (int)Math.Ceiling((double)_result.TotalCount / PageSize);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task HandleFiltersApplied(ProductFilter filter)
    {
        _filter = filter;
        _currentPage = 1;
        await SearchAsync();
    }

    private async Task HandleFiltersCleared()
    {
        _filter = new ProductFilter(null, null, null, false);
        _currentPage = 1;
        await SearchAsync();
    }

    private async Task HandleSortChanged(string sortBy)
    {
        _sortBy = sortBy;
        _currentPage = 1;
        await SearchAsync();
    }

    private async Task HandlePageChanged(int page)
    {
        _currentPage = page;
        await SearchAsync();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder for cart functionality
        return Task.CompletedTask;
    }
}

