    display: flex;
    align-items: center;
    justify-content: center;
    color: #999;
    font-size: 0.9rem;
}

.product-info {
    padding: 1rem;
}

.product-name {
    margin: 0 0 0.5rem;
    font-size: 1rem;
}

.product-price {
    font-weight: bold;
    color: #2e7d32;
    margin: 0 0 0.5rem;
}

.product-rating {
    color: #f59e0b;
    margin-bottom: 0.5rem;
}

.badge-out-of-stock {
    display: inline-block;
    background: #dc3545;
    color: white;
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
    font-size: 0.75rem;
    margin-bottom: 0.5rem;
}

.btn-add-to-cart {
    width: 100%;
    padding: 0.5rem;
    background: #0d6efd;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-add-to-cart:hover:not(:disabled) {
    background: #0b5ed7;
}

.btn-add-to-cart:disabled {
    background: #ccc;
    cursor: not-allowed;
}

.pagination-controls {
    display: flex;
    justify-content: center;
    gap: 0.5rem;
    padding: 1rem 0;
}

.btn-page {
    padding: 0.4rem 0.8rem;
    border: 1px solid #dee2e6;
    background: white;
    border-radius: 4px;
    cursor: pointer;
}

.btn-page:hover:not(:disabled) {
    background: #e9ecef;
}

.btn-page:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.btn-page.active {
    background: #0d6efd;
    color: white;
    border-color: #0d6efd;
}

.catalog-loading,
